data.transform:
$state.context.value.after.{
  "create":{
    "id": id,
    "name": name,
    "description": description,
    "deviceSubscriptionTypeId": "nodeValues",
    "deviceGatewayDeviceId": $state.context.deviceGatewayDeviceId,
    "updateFrequencySeconds": 0,
    "configuration":{
      "nodes": [ configuration.nodeId ],
      "continuousValues": false,
      "storeAndForward": false
    }

  }
}

data.query:
query ($deviceId: String!){
  deviceGatewayDevice(
    where:{
      deviceId:{_eq: $deviceId}
    }
    first:1
  ){
    total
    edges{
      node{
        id
      }
    }
  }


}

data.mutation:
mutation ($create: DeviceSubscriptionCreateInput!){
  createDeviceSubscription(
    payload:{
      create: $create
    }
){
  id
}
}

mutation ($id: ID!){
  deleteDeviceSubscription(
    payload:{
      where:{
        id: $id
      }
    }
  ){
    id
  }
}

